-- Risdel Books Module 29 - Documents & Attachments Centre
-- Future relational migration reference. Metadata is provider-neutral; file binaries remain in external storage.
CREATE TABLE Documents_Documents (Id uniqueidentifier PRIMARY KEY, DocumentNumber nvarchar(50) NOT NULL UNIQUE, Title nvarchar(250) NOT NULL, DocumentType nvarchar(80), Category nvarchar(80), Description nvarchar(max), OriginalFileName nvarchar(260), MimeType nvarchar(120), FileExtension nvarchar(20), FileSize bigint, StorageProvider nvarchar(50), StorageKey nvarchar(500), StorageUrl nvarchar(1000), CurrentVersion int NOT NULL DEFAULT 1, Status nvarchar(30), Confidentiality nvarchar(30), OwnerUserId uniqueidentifier NULL, UploadedBy uniqueidentifier NULL, CreatedAt datetime2 NOT NULL, UpdatedAt datetime2 NULL, ArchivedAt datetime2 NULL, IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE Documents_Links (Id uniqueidentifier PRIMARY KEY, DocumentId uniqueidentifier NOT NULL, EntityType nvarchar(80) NOT NULL, EntityId nvarchar(100) NOT NULL, EntityNumber nvarchar(100), RelationshipType nvarchar(50), CreatedAt datetime2 NOT NULL, CreatedBy uniqueidentifier NULL, IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE Documents_Versions (Id uniqueidentifier PRIMARY KEY, DocumentId uniqueidentifier NOT NULL, VersionNumber int NOT NULL, OriginalFileName nvarchar(260), MimeType nvarchar(120), FileSize bigint, StorageProvider nvarchar(50), StorageKey nvarchar(500), StorageUrl nvarchar(1000), Checksum nvarchar(128), ChangeNotes nvarchar(1000), UploadedBy uniqueidentifier NULL, UploadedAt datetime2 NOT NULL, IsCurrent bit NOT NULL DEFAULT 0, IsActive bit NOT NULL DEFAULT 1);
